    "h_statements": [
      {
        "code": "H315",
        "text": "피부에 자극을 일으킴",
        "line": "p1:L21"
      },
      {
        "code": "H319",
        "text": "눈에 심한 자극을 일으킴",
        "line": "p1:L22"
      }
    ],
    "p_statements": [
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p1:L24"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "(보호장갑·보호의·보안경·안면보호구)를(을) 착용하시오.",
        "line": "p1:L25"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면 다량의 비누와 물로 씻으시오.",
        "line": "p1:L26"
      },
      {
        "code": "P302+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p1:L27"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "(…) 처치를 하시오.",
        "line": "p2:L1"
      },
      {
        "code": "P332+P313",
        "type": "대응",
        "text": "피부 자극이 생기면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L2"
      },
      {
        "code": "P337+P313",
        "type": "대응",
        "text": "눈에 자극이 지속되면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L3"
      },
      {
        "code": "P362",
        "type": "대응",
        "text": "오염된 의복은 벗고 다시 사용 전 세탁하시오.",
        "line": "p2:L4"
      }
    ],
    "nfpa": {
      "health": 1,
      "fire": 0,
      "reactivity": 0,
      "special": "자료없음"
    },
    "lines": {
